window.__saqPaperQuestions("2024-1-pah",[{"number":1,"title":"","stemText":"A 60 year old woman has presented to ED with visual disturbance.\nA clinical photograph is shown below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the abnormalities in the photo, including your clinical impression. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 potential causes for this problem. For each, provide the diagnostic assessment\nfinding/s from history, examination or investigation. (8 marks) Cause Assessment finding/s"}],"propPages":["asset:imgbe3dfe80330bc05fc0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Left ptosis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Dilated pupil</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Eye down and out</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Diabetic neuropathy – Hx DM, no other cause found, poor glucose control</td><td>CVA brainstem – found on MRI brain</td></tr><tr><td>Cavernous sinus thrombosis – CTV/MRV brain</td><td>MS – demyelinating lesions on MRI</td></tr><tr><td>Brain tumour compressing CN III – CT brain + C</td><td>Raised ICP from obstructive hydrocephalus – CT brain</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 72 year old man has presented to the ED after having a syncopal event at home.\nHis ECG is presented below.","parts":[{"id":"p1","label":"Part 1","prompt":"State 3 points in your description of the ECG. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"Provide your clinical impression and implication for management from the information provided. (2 marks) Shortly after arrival, a duress alarm has been called to the patient’s cubicle.\nHis vital signs are:\n\nGCS\nE3 V3 M5\n\nHR\n/min\n\nBP\n70/40 mmHg O2 sats 99% RA"},{"id":"p3","label":"Part 3","prompt":"State 3 medications you might use to increase his heart rate, including doses. For each,\nprovide the rationale for its preferential use. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 3 settings (on the defibrillator after selecting the pacing function) you would choose when initiating electrical pacing. (3 marks)"}],"propPages":["asset:img037d97f73a386efea5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">First degree HB – prolonged PR</div><div class=\"answer-line\">LBBB</div><div class=\"answer-line\">bifascicular with first degree HB</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Syncope will have been due to complete AV block</div><div class=\"answer-line\">Pacemaker needed</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Medication</th><th>Justification</th></tr></thead><tbody><tr><td>Atropine 1mg – use if junctional escape to increase rate</td><td>Isoprenaline infusion – to increase HR where no requirement for vasopressor use</td></tr><tr><td>Adrenaline infusion – use where profound shock as it increases chronotropy and inotropy as well as</td><td>vasopressor</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Demand mode</div><div class=\"answer-line\">Rate 60-70/min</div><div class=\"answer-line\">Current – approx. 80mA – increase until electrical and mechanical capture achieved</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 4 year old girl has been brought to the ED with abdominal pain of 4 hours duration.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 important features of your history. Include justification. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 important features of your examination. Include justification. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 investigations you might perform. Provide the clinical indication for each. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Dysuria – UTI common cause of abdo pain</div><div class=\"answer-line\">PMHx- looking for previous abdominal surgeries – likely bowel obstruction from adhesions</div><div class=\"answer-line\">Allergies – avoid certain antibiotics eg penicillins</div><div class=\"answer-line\">Location of pain – eg RLQ – appendicitis</div><div class=\"answer-line\">Fever – infective aetiology</div><div class=\"answer-line\">Cough – pneumonia as a cause</div><div class=\"answer-line\">Previous trauma – intra-abdominal organ injury</div><div class=\"answer-line\">Bilious vomiting – post-biliary obstruction as cause</div><div class=\"answer-line\">Diarrhoea – gastroenteritis as cause</div><div class=\"answer-line\">Travel hx – endemic gastroenteritis as cause and may alter antibiotic selection</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Location of tenderness – to localize pathology eg RLQ – appendicitis</div><div class=\"answer-line\">Presence of peritonism – will need more urgent workup and imaging for possible surgery</div><div class=\"answer-line\">Look for inguinal herniae – will need surgical correction</div><div class=\"answer-line\">Chest auscultation – pneumonia</div><div class=\"answer-line\">Bruising over soft tissues/burns/finger marks – NAI risk</div><div class=\"answer-line\">Bowel sounds – Tinkling suggestive of obstruction</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Urine M/C/S – in pt with fever / urinary symptoms</td><td>VBG – perform in shocked pt to evaluate acid-base – guide resuscitation</td></tr><tr><td>BSL – diabetic pt – exclude DKA as a cause of abdominal pain</td><td>USS – in pt with possible appendicitis but not clinically obvious enough to go straight to OT</td></tr><tr><td>CT abdomen – Peritonism or concern for NAI</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 45 year old woman has been referred to the ED by her GP.\nShe was found to have an elevated serum calcium level on blood tests performed to investigate symptoms of general fatigue and malaise.\nHer serum Ca level is 3.8 mmol/L (ref range 2.1 - 2.6).","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 symptoms of severe hypercalcaemia (apart from fatigue / malaise). (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you would perform. Include justification for each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 treatments you could use to manage her severe hypercalcaemia. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Confusion</div><div class=\"answer-line\">Abdominal pain from constipation</div><div class=\"answer-line\">Bone pain</div><div class=\"answer-line\">Kidney stones – pain, haematuria etc</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Chem 20 – look for renal failure contributing</td><td>PTH – look for hyperparathyroidism</td></tr><tr><td>CXR – exclude lung malignancy causing high Ca</td><td>ECG – look for short QT – risk arrhythmias</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">IV fluid – N/S 1L</div><div class=\"answer-line\">IV frusemide after fluid – 40mg</div><div class=\"answer-line\">IV bisphosphonate – eg IV pamidronate (or other)</div><div class=\"answer-line\">Calcitonin</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 12 month old boy has been brought to the ED by his mother. He has developed lesions around his mouth and has been unable to eat or drink. A photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State 3 abnormalities evident in the photograph. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 potential diagnoses. For each provide a supportive finding from your history or\nexamination. (6 marks) Diagnosis Assessment finding"},{"id":"p3","label":"Part 3","prompt":"List 3 investigations you might perform. Provide justification for each. (3 marks)"}],"propPages":["asset:imgf94e99d11def50af54"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Several vesicular lesions face and upper torso</div><div class=\"answer-line\">Pale, unwell child / sleepy</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Herpes simplex – parent / contact with herpetic lesions mouth</td><td>SJS / drug reaction – exposure to new drug eg NSAID</td></tr><tr><td>Hand/foot/mouth / coxsackie virus – vesicle on palms and soles</td><td>VZV – Recent exposure to chicken pox / non-immunised</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Viral PCR swab of vesicles to confirm herpes simplex/VZV</td><td>Chem 20 – exclude renal failure from poor oral intake – ensure K not high</td></tr><tr><td>VBG – if vital signs suggest shock, to define degree of hypoperfusion and use serial measurements to</td><td>guide resuscitation eg lactate, degree of metabolic acidosis</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 25 year old woman has been taken to the ED by ambulance after having a self-terminating seizure at a nightclub. Collateral history on scene indicated she had been using drugs during the evening.\nHer vital signs on arrival to the ED are:\n\nGCS\nE2 V2 M5\n\nHR\n135 /min\n\nBP\n155/85 mmHg O2 sats 99% RA Temperature 41.5 degrees","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 toxidromes that might cause this clinical picture. Provide the examination features that would be consistent with each. (6 marks) Toxidrome Examination features"},{"id":"p2","label":"Part 2","prompt":"List 6 investigations you might perform in the ED. Provide justification for each. (6 marks) Shortly after arrival, the patient has another seizure. An initial dose of 5mg of midazolam IV has failed to terminate the seizure."},{"id":"p3","label":"Part 3","prompt":"State 5 components of your management. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Sympathomimetic – sweaty, mydriasis, tachyarrhythmias, tremor, agitation</div><div class=\"answer-line\">Serotonin toxicity – mydriasis, rigidity, hyper-reflexia,</div><div class=\"answer-line\">Anti-cholinergic – hot, red, dry, normal tone/reflexes</div><div class=\"answer-line\">NMS – hypertonia, depressed reflexes, decreased LOC (not agitated)</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>K – exclude life-threatening hyperK due to rhabdo</td><td>ECG – exclude severe hyper K, look for arrhythmia</td></tr><tr><td>Urea/creat – exclude ARF due to rhabdo</td><td>CT head – exclude ICH as cause of seizures / complication of hypertension / consequence of trauma</td></tr><tr><td><strong>Na</strong> – hyponatremia common cause of seizures / due to MDMA use</td><td>BC – sepsis a possibility to rationalise Abs during admission</td></tr><tr><td>LP – to exclude meningitis / encephalitis if no suspicion of raised ICP</td><td>Others will be OK</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Further IV midaz 5mg</td></tr><tr><td colspan=\"2\">Initiate Keppra 2g IV aiming to terminate seizure</td></tr><tr><td colspan=\"2\">Will require intubation given severe hyperthermia</td></tr><tr><td>-</td><td>Propofol 2mg/kg induction / roc 1.2mg/kg</td></tr><tr><td colspan=\"2\">Active cooling</td></tr><tr><td>-</td><td>Start cold IV fluids 1l N/S stat 4 degrees</td></tr><tr><td>-</td><td>Cooling blanket</td></tr><tr><td colspan=\"2\">IV Abs</td></tr><tr><td colspan=\"2\">To cover septic shock / meningitis / encephalitis</td></tr><tr><td colspan=\"2\"><strong>Must give an anti-convulsant </strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 58 year old man has presented with macroscopic haematuria of 2 days duration.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 potential differential diagnoses. For each, provide a supportive finding on your\nhistory. (8 marks) Diagnosis Supportive finding on history"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you might perform. For each, provide the clinical justification for its use. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cystitis / UTI – dysuria, fevers</td><td>Renal stone – flank pain, Hx stones</td></tr><tr><td>Renal Ca – painless, Hx of malignancy</td><td>Bladder cancer – painless, B symptoms</td></tr><tr><td>Renal vein thrombosis - Thrombophilia</td><td>Renal artery embolism – Hx of AF</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>CT KUB – if renal stones suggested</td><td>Urine cytology – if painless haematuria to look for Ca</td></tr><tr><td>Bladder scan – exclude clot retention where lots of pain / can’t urinate</td><td>Urea/create – look for renal failure</td></tr><tr><td>Others OK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 45 year old man has presented with abdominal pain.\nAn abdominal x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State the abnormalities shown on the x-ray, including your conclusion. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 features of your examination, including the relevance of each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 investigations you would perform. Include the clinical justification for each.\n(4 marks)"}],"propPages":["asset:img9bd252b8fe91b5715b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Multiple air-fluid levels</div><div class=\"answer-line\">Large bowel devoid of gas</div><div class=\"answer-line\">Valvulae conniventes confirming small bowel</div><div class=\"answer-line\"><strong>Conclusion - Small bowel obstruction </strong></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Peritonism – Likely require laparotomy and broad-spectrum antibiotic coverage</div><div class=\"answer-line\"><strong>Vital signs</strong> – If evidence of septic shock need broad-spectrum antibiotic coverage and laparotomy</div><div class=\"answer-line\"><strong>Hernial orifices – For cause of obstruction </strong></div><div class=\"answer-line\">Bowel sounds – Tinkling or absent – Suggests obstruction vs. paralytic ileus</div><div class=\"answer-line\">Surgical scars – suggest adhesions as cause</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>VBG – Lactate to suggest bowel ischaemia +- septic shock state</td><td>Chem20 – Hypokalaemia in setting of profuse vomiting</td></tr><tr><td>CT abdomen + C – Identify lead point + evidence of bowel ischaemia</td><td>CXR – Rule out aspiration given likelihood of vomiting</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 65 year old woman has been taken to the ED with large volume haematemesis.\nShe has a history of alcoholism and type 1 diabetes mellitus. An arterial blood gas has been provided below. Arterial blood gas\n\nFiO2\n0.90\n\npH\n7.17 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\nmmHg (60 - 100)\n\nHCO3\nmmol/L (22 - 32)\n\nNa\n117 mmol/L (135 - 145)\n\nK\n3.5 mmol/L (3.5 - 5.2)\n\nCl\nmmol/L (95 - 110)\n\nGlucose\n34.3 mmol/L (3.0 - 7.8)\n\nLactate\n8.1 mmol/L (0.5 - 2.2)\n\nHb\ng/L (115 - 160)","parts":[{"id":"p1","label":"Part 1","prompt":"State 3 acid-base disturbances. Provide the calculations and likely causes for each.\n(9 marks) Acid-Base disturbance Calculations Likely cause"},{"id":"p2","label":"Part 2","prompt":"Briefly explain the likely factors influencing the sodium of 117. (3 marks) The patient has the following vital signs:\n\nGCS\nE3 V4 M6 Pulse 125 /min\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 92% 15L O2 via non-rebreather Temperature 36.0 degrees"},{"id":"p3","label":"Part 3","prompt":"State 6 components of your management of the patient. (6 marks)\nPAH 2024.1 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>AG = 117 – (64 + 11) = 42</td><td>Diabetic ketoacidosis + lactate</td></tr><tr><td><strong>HAGMA </strong></td><td></td></tr><tr><td>Delta = 42 – 12 / 24 – 11</td><td>Hypochloraemic NAGMA likely</td></tr><tr><td>Metabolic alkalosis</td><td>= 30 / 13 secondary to profuse vomiting</td></tr><tr><td>= &gt;2</td><td></td></tr><tr><td>Predicted CO2 = 1.5 x HCO3 +</td><td>Aspiration causing</td></tr><tr><td>8</td><td>hypoventilation through VQ</td></tr><tr><td>Relative respiratory acidosis</td><td>= 1.5 x 11 + 8 = 25 mismatch</td></tr><tr><td>Actual CO2 is 32</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">- dilutional hyponatraemia secondary to hyperglycaemia</div><div class=\"answer-line\">- Hypovolaemic hyponatraemia secondary to volume loss from vomiting + osmotic diuresis with</div><div class=\"answer-line\">solute drag at kidneys from glucose and ketones</div><div class=\"answer-line\">CLD</div><div class=\"answer-line\">Diet related eg beer potomania</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Low threshold for peripheral noradrenaline</div><div class=\"answer-line\">Ceftriaxone 2g IV stat</div><div class=\"answer-line\">Pantoprazole 80mg IV stat then infusion</div><div class=\"answer-line\">Octreotide 50mcg IV stat then 50mcg/hr</div><div class=\"answer-line\">Correct any coagulopathy identified given likely liver disease</div><div class=\"answer-line\"><strong>Organise endoscopy </strong></div><div class=\"answer-line\"><strong>Insulin infusion at 0.1IU/kg/hr </strong></div><div class=\"answer-line\">N/saline 1L stat then reassess fluid responsiveness</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"An 8 year old girl has presented to your rural ED with fevers, shortness of breath and a productive\ncough for the past 6 days.\nHer chest x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the x-ray. (3 marks)\nHer vital signs are:\n\nGCS\nPulse 140 /min\n\nBP\n75/40 mmHg\n\nRR\n/min O2 sats 90% 15L O2 via non-rebreather mask\n\nWeight\nkg You have decided that the patient requires intubation with subsequent ICC insertion."},{"id":"p2","label":"Part 2","prompt":"Complete the following table for this patient. (4 marks) Size of endotracheal tube (ETT) Depth of ETT insertion Dose of ketamine for induction Dose of rocuronium"},{"id":"p3","label":"Part 3","prompt":"State 4 components of your management of this patient (apart from the information given\nabove), including your management of the peri-intubation period. (4 marks)"},{"id":"p4","label":"Part 4","prompt":"Provide your initial ventilator settings. (2 marks) Tidal volume Peak Pressure Cut-off You have decided to insert a small bore inter-costal catheter with a Seldinger technique."},{"id":"p5","label":"Part 5","prompt":"List 4 potential complications of this procedure. For each, state the safety step you will adopt to prevent its occurrence. (4 marks)"}],"propPages":["asset:imgde5a7b388832081585"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Right middle/lower lobe consolidation concerning for pneumonia</div><div class=\"answer-line\">Right horizontal fissure fluid/plate atelectasis</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">1.</div><div class=\"answer-line\"><strong>Right parapneumonic effusion/empyema </strong></div><div class=\"answer-line\">Right middle/lower lobe consolidation concerning for pneumonia</div><div class=\"answer-line\">Right horizontal fissure fluid/plate atelectasis</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Something about positioning would be fine</div><div class=\"answer-line\">Adrenaline infusion titrated to systolic &gt;90</div><div class=\"answer-line\"><strong>IV N/saline 20mL/kg bolus </strong></div><div class=\"answer-line\"><strong>BenPen 60mg/kg IV q6h + Lincomycin IV 15mg/kg q8h (QCH guideline) </strong></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">150-200mL</div><div class=\"answer-line\">40cmH20 +/- 5</div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Traumatic lung injury – USS prior needle insertion to ensure fluid pocket present</td><td>Traumatic liver injury – Ensure anatomical landmarks identified and triangle of safety utilised</td></tr><tr><td>IC nerve/vessel injury – Above rib below</td><td>Cardiac injury – Careful insertion of needle, aspirating on insertion to ensure needle passed only as</td></tr><tr><td>far as required to allow wire to enter thoracic cavity</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 34 year old man has been taken to your tertiary ED after being hit by a car while walking across the street. The x-ray of his pelvis is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the abnormalities shown. (3 marks) An image from the RUQ view of his FAST scan is provided below."},{"id":"p2","label":"Part 2","prompt":"Interpret the image. (1 mark) His chest x-ray is normal.\nHis vital signs are as follows:\n\nGCS\nE3 V4 M6 Pulse 140 /min\n\nBP\n70/50 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"p3","label":"Part 3","prompt":"List 3 clinical end-points you would target in your initial resuscitation. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 3 differences between ROTEM guided and ratio guided resuscitation techniques.\n(3 marks)"},{"id":"p5","label":"Part 5","prompt":"State 6 factors you would consider in determining whether to perform a CT scan for this\npatient. Include the clinical relevance of each factor. (6 marks)"}],"propPages":["asset:img08386513ca8a2fe6c0","asset:img8f6f4ed3d38d3a7822"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>Left lateral compression fracture</strong> of the pelvis with fractures of the left iliac wing through to the SI</div><div class=\"answer-line\">joint and the superior and inferior pubic rami on the left.</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Grossly positive FAST</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">SBP 80mmHg or</div><div class=\"answer-line\">adequate mentation</div><div class=\"answer-line\">radial pulse</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">ROTEM-guided is in real-time</div><div class=\"answer-line\">ROTEM-guided proven to reduce blood product usage</div><div class=\"answer-line\">ROTEM-guided can measure hyperfibrinolysis</div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">Proximity of CT scanner – The closer the more likely</div><div class=\"answer-line\">Clinical suspicion of most significant site of bleeding i.e. if FAST scan volume rapidly increasing -&gt; Red</div><div class=\"answer-line\">blanket vs. small stable positive FAST</div><div class=\"answer-line\">Theatre preparedness to accept red blanket immediately – If delay then may benefit from CT in</div><div class=\"answer-line\">interim</div><div class=\"answer-line\">Clinical suspicion of other time critical injuries i.e. traumatic brain injury given low GCS</div><div class=\"answer-line\">Ability to resuscitate within the CT scanner – If able, more likely to take patient there</div><div class=\"answer-line\">Fluid responsiveness – If responding with boluses of product then more likely to take to CT</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 74 year old man has presented via ambulance with shortness of breath and chest pain for the last 2 days. He has a history of type 2 diabetes mellitus and ischaemic heart disease, having had a stent in his\nright coronary artery 6 years ago.\nHis ECG is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide 4 abnormalities shown on the ECG and your overall interpretation. (5 marks)\nAbnormalities Overall interpretation\nHis vital signs are:\n\nGCS\nPulse 110 /min\n\nBP\n70/30 mmHg\n\nRR\n/min O2 sats 90% 6L O2 via Hudson mask Examination reveals no murmur, full field crepitations, cool peripheries and a weak peripheral pulse."},{"id":"p2","label":"Part 2","prompt":"State 7 components of your management in the ED. (7 marks)"}],"propPages":["asset:img3b5dd2ebcc8b091d93"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Anterior ST elevation V3/4/5 concerning for anterior STEMI</div><div class=\"answer-line\">Q wave V3/V4 suggestive of completed infarct / missed anterior STEMI</div><div class=\"answer-line\">Q waves II, III, aVF suggestive of old inferior MI</div><div class=\"answer-line\">Sinus tachycardia at rate of 140</div><div class=\"answer-line\">Overall interpretation – Old inferior infarct with likely <strong>new anterior STEMI</strong> with some degree of</div><div class=\"answer-line\">completed infarction</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Aspirin</div><div class=\"answer-line\">ticagrelor</div><div class=\"answer-line\">Heparinisation with dosing</div><div class=\"answer-line\"><strong>Cardiology consultation</strong> for consideration of PCI vs. delayed angiogram +- balloon pump given Q</div><div class=\"answer-line\">waves already present and now pain free</div><div class=\"answer-line\">CPAP/BiPAP with appropriate settings / intubation</div><div class=\"answer-line\">Judicious fluid bolus ?</div><div class=\"answer-line\">Noradrenaline/dobutamine/adrenaline (something sensible)</div><div class=\"answer-line\">ICU referral for admission</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 9 year old girl has presented after falling off a set of monkey bars at school.\nShe has an isolated right elbow injury. X-rays of her elbow are provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the x-ray. (1 mark) A C B D"},{"id":"p2","label":"Part 2","prompt":"Provide labels for the arrowed features on the x-ray. (4 marks) A B C D Ketamine has been administered to provide procedural sedation as part of your patient management. During the procedure, the patient suffers laryngospasm."},{"id":"p3","label":"Part 3","prompt":"State 4 treatment measures you might institute to manage the laryngospasm. State when\nyou would adopt each measure. (4 marks) Following your management, you intend to examine the patient to assess median nerve function."},{"id":"p4","label":"Part 4","prompt":"Complete the table, regarding how you will assess median nerve function. (2 marks) Sensory function Motor function"}],"propPages":["asset:img1cbe1d7e96bde77982"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Posterior elbow dislocation</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">A – olecranon</div><div class=\"answer-line\">B – Radial head</div><div class=\"answer-line\">C – Capitellum</div><div class=\"answer-line\">D – Trochlea</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Larsons point – Initial step along with BVM</div><div class=\"answer-line\">BVM with PEEP valve turned to 15 – Initial step once laryngospasm identified</div><div class=\"answer-line\">Deepen sedation – Failure of PEEP to control laryngospasm and provide adequate ventilation</div><div class=\"answer-line\">Paralyse and intubate – Failure to ventilate despite above</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Sensory – Lateral aspect of palm of hand or 2nd/3rd/lateral half of 4th digit</div><div class=\"answer-line\">Motor – Thumb abduction OR O-sign with thumb IP flexion</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You have received a complaint from a patient regarding a missed injury. The patient was discharged from the ED with a diagnosis of foot sprain. On subsequent assessment by her GP, she was found to have a Lisfranc injury which required surgery at another hospital.","parts":[{"id":"p1","label":"Part 1","prompt":"State 7 pieces of information you will seek from your investigation. Provide justification for each. (7 marks)"},{"id":"p2","label":"Part 2","prompt":"Apart from your investigation, state 5 features of your management of this situation. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Was a CT foot performed? – Was the diagnosis missed through not investigating appropriately or</td><td>through a missed radiological finding or communication breakdown</td></tr><tr><td>What safety netting was provided to the patient? – Was patient told that if symptoms persisted they</td><td>needed to seek further medical input</td></tr><tr><td>What weight-bearing status was the patient instructed to perform? – If weight-bearing then</td><td>significant risk of worsening the injury</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Notify medical officer involved</div><div class=\"answer-line\">Discuss case with them and understand their thinking/rationale behind actions</div><div class=\"answer-line\">Apologise to patient and their family</div><div class=\"answer-line\">Emphasise that the patient and their family will be informed of any findings of the investigation with</div><div class=\"answer-line\">a focus on preventing this type of situation in the future</div><div class=\"answer-line\">Educational materials for department on midfoot injuries and how to avoid missed diagnosis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"You are reading an article about a new anticoagulant for the management of atrial fibrillation (AF).","parts":[{"id":"p1","label":"Part 1","prompt":"Complete the table regarding the interpretation of measurements of central tendency. (6 marks)"},{"id":"p2","label":"Part 2","prompt":"Provide a definition for odds ratio. (1 mark)"},{"id":"p3","label":"Part 3","prompt":"Provide a definition for relative risk. (1 mark) The results of the study describe a 10% relative risk reduction of stroke per year for the new drug in comparison with warfarin. The study reports a stroke risk of 5% per year for patients on warfarin."},{"id":"p4","label":"Part 4","prompt":"In a population of 1000 patients with AF, provide the number of patients that would be\nexpected to suffer a stroke on each medication. (2 marks) Warfarin New drug"},{"id":"p5","label":"Part 5","prompt":"What is the absolute risk reduction of stroke in this cohort on the new drug? (1 mark)"},{"id":"p6","label":"Part 6","prompt":"What is the number needed to treat to prevent one stroke by using the new drug instead\n• f warfarin? (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>(6/12) </strong></div><div class=\"answer-line\">Descriptive statistic</div><div class=\"answer-line\">Issue with use</div><div class=\"answer-line\">Mean</div><div class=\"answer-line\">Sum of all observations /</div><div class=\"answer-line\">Can be highly effected by</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">The ratio of the probability of one event occurring and the probability that the event will never occur</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">The risk of an event in an experimental group divided by the risk in the control group</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Drug</td><td>Number of strokes per year</td></tr><tr><td>Warfarin</td><td>50</td></tr><tr><td>New drug</td><td>45</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">5/1000 = 0.5%</div></section><section class=\"answer-part\"><h5>Part 6</h5><div class=\"answer-line\">1/0.005 = 200</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 47 year old man has presented with right sided flank pain and fever.\nTwo slices from his CT scan are provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State 3 abnormalities from the CT scans. Include your clinical interpretation. (4 marks)\nRadiographic abnormalities Clinical interpretation\nHis vital signs are:\n\nGCS\nPulse 120 /min\n\nBP\n80/40 mmHg\n\nRR\n/min O2 sats 100% room air"},{"id":"p2","label":"Part 2","prompt":"State 4 components of your management. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 risk factors for the development of this pathology. (4 marks)"}],"propPages":["asset:imga348894a952e51d0c8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Right mid-ureteric stone</div><div class=\"answer-line\">Right hydroureter/hydronephrosis</div><div class=\"answer-line\">Subtle perinephric stranding</div><div class=\"answer-line\"><strong>Infected obstructed right kidney/ureter </strong></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">IV N/saline 1L stat</div><div class=\"answer-line\">Early noradrenaline titrated targeting MAP 65mmHg</div><div class=\"answer-line\"><strong>Urology consultation for stenting </strong></div><div class=\"answer-line\">ICU consultation for admission if requiring vasopressors</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Immobilisation (calcium from bone turnover)</div><div class=\"answer-line\">Excess dietary sodium – Promotes hypercalciuria</div><div class=\"answer-line\">Gout – Hyperuricosuria</div><div class=\"answer-line\">Primary hyperparathyroidism – Hypercalciuria</div><div class=\"answer-line\">Low urine volume – may allow supersaturation</div><div class=\"answer-line\">Family history</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"You are the director of a metropolitan ED. You are chairing a consultant staff meeting to discuss the extreme overcrowding your ED has been experiencing.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide a definition for ED overcrowding. (1 mark)"},{"id":"p2","label":"Part 2","prompt":"Provide a definition for access block. (1 mark)"},{"id":"p3","label":"Part 3","prompt":"List 4 adverse effects of ED overcrowding. (4 marks)"},{"id":"p4","label":"Part 4","prompt":"State 6 interventions your ED could institute aimed at reducing ED overcrowding.\n(6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Situation where ED function is impeded because the number of patients exceeds either the physical</div><div class=\"answer-line\">and/or staffing capacity of the ED</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Percentage of patients admitted or planned for admission but discharged from the ED without</div><div class=\"answer-line\">reaching an inpatient bed, transferred to another facility, or died in the ED whose total ED time</div><div class=\"answer-line\">exceeded eight hours.</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Increased risk of adverse events</div><div class=\"answer-line\">violent incidents</div><div class=\"answer-line\">errors and near misses</div><div class=\"answer-line\">delayed time to definitive care</div><div class=\"answer-line\">excess morbidity and mortality</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Mandatory notification of 12 and 24 hours stays</div><div class=\"answer-line\">Alternative care options e.g. Virtual ED</div><div class=\"answer-line\">Matching throughput to daily demand (active bed management)</div><div class=\"answer-line\">Reliable capacity measures</div><div class=\"answer-line\">Time-based targets for all units (not just ED)</div><div class=\"answer-line\">Afterhours radiology/pathology/rounding.etc.</div><div class=\"answer-line\">Optimal patient workup and referral pathways</div><div class=\"answer-line\">Clear escalation policy for overcrowding</div><div class=\"answer-line\">Formal referral pathways for common presentations e.g. chest pain</div><div class=\"answer-line\">Many others</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 30 year old woman has collapsed at triage after self-presenting with fatigue and difficulty\nbreathing. She is 35 weeks pregnant.\nShe has been quickly transferred to a resuscitation room. Initial assessment reveals the patient to be in pulseless electrical activity (PEA).","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 components of your initial management. (4 marks)\nYou have elected to use bedside USS to guide your further management."},{"id":"p2","label":"Part 2","prompt":"State 5 findings from bedside USS that would change your management. Provide\nexplanation for each. (5 marks) An image from your bedside USS is provided below. The patient has a return of spontaneous circulation."},{"id":"p3","label":"Part 3","prompt":"State 3 options for managing the above pathology in this patient. (3 marks)\nPAH 2024.1 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":["asset:img6b1d772ab885f1ca70"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Intubation</div><div class=\"answer-line\"><strong>Adrenaline 1mg IV bolus  </strong></div><div class=\"answer-line\">Prepare for peri-mortem C/S if no ROSC within 5 minutes</div><div class=\"answer-line\">Left lateral tilt or uterine manual displacement</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cardiac tamponade – Pericardiocentesis</td><td>Dilated RV – Lysis for PE</td></tr><tr><td>Clot in RA/RV – Lysis for PE</td><td>McConnell’s sign – Lysis for PE</td></tr><tr><td>Collapsed IVC – 2L N/saline bolus</td><td>No lung sliding – Decompress potential tension pneumothorax</td></tr><tr><td>Absent cardiac activity – Perimortem C/S immediately</td><td>Very poor LV contractility – Concern for myocarditis -&gt; Maximise inotropic support</td></tr><tr><td>DVT</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">IV lysis</div><div class=\"answer-line\">Heparinisation</div><div class=\"answer-line\">Thrombectomy</div><div class=\"answer-line\">ECMO</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 69 year old man has presented with increasing headache over several weeks.\nHe is on rivaroxaban for atrial fibrillation. A slice from his CT head is provide below.","parts":[{"id":"p1","label":"Part 1","prompt":"State the pathology demonstrated, with 4 radiographic abnormalities. (5 marks) Pathology Radiographic abnormalities Whilst in the department, there has been a deterioration in the patient’s level of consciousness."},{"id":"p2","label":"Part 2","prompt":"List 6 potential causes for his deterioration. (6 marks)\nHis vital signs are:\n\nGCS\nE1 V2 M3 Pulse 110 /min\n\nBP\n220/110 mmHg\n\nRR\n/min O2 sats 88% room air"},{"id":"p3","label":"Part 3","prompt":"State 6 components of your management. (6 marks)"}],"propPages":["asset:img47a7a25ffce8b555ec"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Right frontal acute on chronic subdural haematoma</div><div class=\"answer-line\">Midline shift towards right</div><div class=\"answer-line\">Lateral ventricle compression</div><div class=\"answer-line\">Subfalcine herniation towards right</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Uncal herniation</div><div class=\"answer-line\">Seizure</div><div class=\"answer-line\">Hyponatraemia secondary to SIADH/cerebral salt wasting</div><div class=\"answer-line\">Acute extra-axial haemorrhage</div><div class=\"answer-line\">Hypoxia secondary to airway obstruction owing to reduced GCS</div><div class=\"answer-line\">Hypercarbia secondary to airway obstruction</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">3% Hypertonic saline 3mL/kg</div><div class=\"answer-line\">Hyperventilate to PaCo2 30mmHg pending neurosurgical intervention</div><div class=\"answer-line\">Head up 30 degrees</div><div class=\"answer-line\">Heavy ongoing sedation and paralysis to reduce ICP</div><div class=\"answer-line\">Keppra load 30mg/kg IV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 28 year old woman has presented with severe lower abdominal pain and fever.","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 features of your history and examination that would be consistent with pelvic\ninflammatory disease (PID). (6 marks) Your assessment is consistent with severe PID."},{"id":"p2","label":"Part 2","prompt":"List 3 investigations you would perform. Provide justification for each. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State your antibiotic therapy with rationale. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Recent unprotected sex</div><div class=\"answer-line\">Previous history of STI/PID</div><div class=\"answer-line\">New vaginal discharge</div><div class=\"answer-line\">RUQ pain consistent with Fitz-Hugh-Curtis syndrome</div><div class=\"answer-line\">Cervical excitation</div><div class=\"answer-line\">Adnexal tenderness</div><div class=\"answer-line\">Adnexal mass consistent with tubo-ovarian abscess</div><div class=\"answer-line\">Cervical inflammation on speculum examination</div><div class=\"answer-line\">Fever</div><div class=\"answer-line\">Dyspareunia</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Endocervical swab PCR – For Chlamydia trachomatis and Neisseria gonorrhoeae</td><td><strong>hCG – Rule in/out pregnancy and would change inpatient vs. outpatient care </strong></td></tr><tr><td>USS pelvis – To rule in/out tubo-ovarian abscess that may require surgical drainage</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Ceftriaxone 2g IV daily – for Gono</div><div class=\"answer-line\">Azithromycin 500mg IV daily – for Chlamydia</div><div class=\"answer-line\">Metronidazole 500mg IV BD – for Trich</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 7 day old boy has been brought to the ED with 1 day of vomiting and lethargy.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 key features of your history. Include the relevance of each. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 key features of your examination. Include the relevance of each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 investigations you might perform. Provide the clinical indication for each.\n(4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Antenatal screening – Any concerns for congenital cardiac disease</div><div class=\"answer-line\">Preterm birth – Increased risk of NEC</div><div class=\"answer-line\">Fevers – Increases risk of sepsis as a cause for presentation</div><div class=\"answer-line\">GBS status of mother – If positive, increases risk of GBS sepsis</div><div class=\"answer-line\">Bilious vomiting – Concern for obstructive cause for vomiting illness</div><div class=\"answer-line\">Sick contacts – May increase risk of infective aetiology e.g. chickenpox</div><div class=\"answer-line\">FHx – Endocrine issues as may increase risk of CAH</div><div class=\"answer-line\">Any concerns about ambiguous genitalia – Increased risk of CAH</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Murmur – To assess for congenital cardiac disease</div><div class=\"answer-line\">Saturation differential – to screen for congenital cardiac disease</div><div class=\"answer-line\"><strong>Vitals -</strong> Fever, HR in particular to assess severity/presence of shock state and potential infective</div><div class=\"answer-line\">aetiology</div><div class=\"answer-line\">Abdominal examination – Tender/tense abdomen may increase likelihood of NEC/perforation</div><div class=\"answer-line\">Hernial orifices – Check for incarcerated hernia as may be evidence of obstructive aetiology</div><div class=\"answer-line\">Genitalia – Ambiguity increases risk of CAH</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>BSL –</td><td>BC x 2  -</td></tr><tr><td>TFT –</td><td>VBG/Chem20 – Check K in setting of vomiting + Na</td></tr><tr><td>VBG – Lactate – Assess severity of shock state</td><td>Head CT – Concern for NAI and traumatic brain injury</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 28 year old man has presented with an isolated right leg injury after a motorbike accident. An x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Name and grade the injury. (2 marks)"},{"id":"p2","label":"Part 2","prompt":"Provide 3 radiological abnormalities to support this conclusion. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"List 3 complications of this injury. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 4 components of your management. (4 marks)"}],"propPages":["asset:imge2e837d26e0e4e4e39"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Schatzker VI</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Spiral fracture of diaphysis</div><div class=\"answer-line\">Vertical fracture of metaphysis through articular surface at level of tibial processes</div><div class=\"answer-line\">Moderate displacement…</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Compartment syndrome</div><div class=\"answer-line\"><strong>Popliteal artery injury </strong></div><div class=\"answer-line\">Ligamentous injury e.g. ACL</div><div class=\"answer-line\">Nerve injury e.g. tibial nerve</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Analgesia – Fentanyl 50mcg q15min targeting comfort</div><div class=\"answer-line\">Long-leg backslab for immobilisation</div><div class=\"answer-line\">Orthopaedic consultation for ORIF</div><div class=\"answer-line\">elevate</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"You are preparing for the arrival of a 35 year old man who has sustained a single stab wound to the left side of his back. The incoming ambulance team have reported that the patient has a pulse of 130 /min and a blood pressure of 95/40 mmHg.","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 potential pathologies you might find on patient arrival. Provide the confirmatory\nfindings from examination or bedside investigation for each. (6 marks) Pathology Confirmatory finding/s"},{"id":"p2","label":"Part 2","prompt":"List 4 blood tests you intend to perform. Provide justification for each. (4 marks)\nFollowing your initial management, the patient was transferred to CT. A slice from the CT portal venous phase of his abdomen is provided below."},{"id":"p3","label":"Part 3","prompt":"Interpret the CT scan. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 3 options for definitive management of this injury. For each, provide the clinical\ncircumstance for its use. (3 marks) Management option Clinical circumstance"},{"id":"p5","label":"Part 5","prompt":"List 2 late complications of this injury. (2 marks)"}],"propPages":["asset:img041d29295861fb3c84"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>No lung sliding on bedside USS of left lung</td><td></td></tr><tr><td>Left tension haemothorax</td><td>CXR showing large haemothorax with mediastinal shift</td></tr><tr><td>towards right</td><td></td></tr><tr><td>Large pericardial effusion with RV collapse on echo</td><td></td></tr><tr><td>Cardiac tamponade</td><td></td></tr><tr><td>Positive FAST</td><td></td></tr><tr><td>Intraperitoneal haemorrhage</td><td></td></tr><tr><td>Spinal hemisection (Brown-</td><td>Ipsilateral weakness and contralateral loss of pain/temp</td></tr><tr><td>Sequard)</td><td>below level of injury</td></tr><tr><td>Left brachial plexus injury</td><td>Mixed myotome/dermatome deficit in left upper limb</td></tr><tr><td>Left axillary artery injury</td><td>Left arm delayed capillary refill or weak/absent radial pulse</td></tr><tr><td>Long thoracic nerve injury</td><td>Left scapular winging</td></tr><tr><td>Aortic injury</td><td>Lower limb weak pulses and/or delayed capillary refill</td></tr><tr><td>Renal injury</td><td>Gross haematuria</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>ROTEM – To guide massive transfusion protocol</td><td>VBG – Lactate to measure severity of shock state</td></tr><tr><td>FBC – Baseline Hb to track over time if concern for ongoing bleeding</td><td>Lipase – Assist in ruling out pancreatic injury from stab wound</td></tr><tr><td><strong>G&amp;H</strong> – Significant risk of haemorrhagic shock and blood product requirement</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Grade VI left renal injury</div><div class=\"answer-line\">retroperitoneal haemorrhage</div><div class=\"answer-line\">? Blush (doesn’t say if arterial or venous phase but looks like portal venous phase)</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>IR – Ongoing blush on CT-A from embolisable vessel</td><td>Conservative – Haemodynamically stabilised</td></tr><tr><td>Open repair – Red blanket or ongoing haemodynamic instability without IR being available or</td><td>possible</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">Urinoma</div><div class=\"answer-line\">CKD</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 48 year old woman has presented with confusion after being found collapsed on the floor of her home. Coagulation studies, performed to investigate multiple sites of bruising, are provided below.\n\nINR\n2.1 PT s (9 - 13)\n\nAPTT\ns (25 - 38) Fibrinogen 1.1 g/L (1.7 - 4.5)","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the results. (2 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 potential causes for this abnormality. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 5 potential complications from a prolonged time lying immobile on the floor. For\neach, state how you will assess for its presence (examination or investigation). (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["dimer mg/L (<0.5)\n\nPlatelets\n*10^9/L (140 - 400)"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Partial DIC</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Malignancy</div><div class=\"answer-line\">Snake bite</div><div class=\"answer-line\">Pancreatitis</div><div class=\"answer-line\">Rhabdomyolysis</div><div class=\"answer-line\">Sepsis</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Pressure areas – Examine skin closely for pressure areas on dependent areas</div><div class=\"answer-line\">Compartment syndrome – Palpate compartments for tense feeling + distal neurological or vascular</div><div class=\"answer-line\">compromise</div><div class=\"answer-line\"><strong>Rhabdomyolysis – CK and U&amp;E </strong></div><div class=\"answer-line\">Reperfusion syndrome – Chem20 for hyperkalaemia, hyperphosphataemia, hypocalcaemia</div><div class=\"answer-line\">Aspiration pneumonia – CXR showing classic right middle zone patchy opacification</div><div class=\"answer-line\">Dehydration – Chem20 for acute kidney injury and raised urea/creatinine ratio</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 6 day old girl has been brought to the ED. Throughout the day she has become lethargic and tachypnoeic. The child has the following vital signs: Intermittent feeble cry Pulse 180\n\nBP\n60/40 mmHg\n\nRR\n/min O2 sats 90% room air Temperature 36.5 degrees There is a loud cardiac murmur on examination. You are concerned about the presence of congenital heart disease with a duct dependent lesion.","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 conditions that would present with cyanosis and 3 conditions that would present\nwithout cyanosis. (6 marks) Cyanotic conditions Acyanotic conditions"},{"id":"p2","label":"Part 2","prompt":"Apart from congenital heart disease, list 2 other potential causes of this presentation. For each, provide a cardinal feature on history or examination. (2 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 components of your management of this child. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Tetralogy of Fallot</td><td>Coarctation of the aorta</td></tr><tr><td>Tricuspid atresia</td><td>Persistent ductus arteriosus</td></tr><tr><td>Transposition of the great arteries</td><td>VSD</td></tr><tr><td>Total anomalous pulmonary venous return</td><td>ASD</td></tr><tr><td colspan=\"2\">AVSD</td></tr><tr><td colspan=\"2\">Aortic stenosis</td></tr><tr><td colspan=\"2\">Pulmonary valve stenosis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Respiratory <strong>sepsis </strong>– Fevers</td><td>Congenital adrenal hyperplasia – Hypoglycaemia</td></tr><tr><td>Respiratory distress syndrome – Preterm birth</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Supplemental oxygen targeting SpO2 94-98%</div><div class=\"answer-line\"><strong>Prostaglandin E1 </strong></div><div class=\"answer-line\">Judicious 10mL/kg fluid bolus</div><div class=\"answer-line\">Urgent Cardiology and NICU consultation</div><div class=\"answer-line\">Adrenaline infusion targeting MAP normal for age</div><div class=\"answer-line\"><strong>Amp 50mg/kg IV q6h + Gent 4mg/kg/dose daily IV </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 5 year old boy has been taken to the ED after falling from his scooter and hitting his head on a concrete footpath.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 findings from your history that would suggest a CT scan is warranted. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 examination findings consistent with a base of skull fracture. (4 marks)\nThe child has had 2 vomits and is complaining of a mild headache 2 hours post the injury. He seems alert. There are no signs of skull fracture. His mother wants to take him home."},{"id":"p3","label":"Part 3","prompt":"State 4 key features of your discussion with the mother. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">LOC &gt; 30 seconds ?</div><div class=\"answer-line\">Seizure</div><div class=\"answer-line\">Known coagulopathy e.g. Haemophilia</div><div class=\"answer-line\">Altered mental status</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Raccoon eyes</div><div class=\"answer-line\">Mastoid haematoma</div><div class=\"answer-line\">Haemotympanum</div><div class=\"answer-line\">CSF leak from nose</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Symptoms and signs to watch for to return</div><div class=\"answer-line\">Significant ICH has not been ruled out at this stage but is unlikely given the findings so far</div><div class=\"answer-line\">Do not need to wake up and review him but important to monitor for signs above over next 24-48</div><div class=\"answer-line\">hours</div><div class=\"answer-line\">Does she understand the risk of potential deterioration and can justify her decision</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 26 year old woman has presented with atraumatic pain and swelling to multiple joints. She has no prior medical history.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 potential differential diagnoses. Provide a supportive finding from history or\nexamination for each diagnosis. (12 marks) Diagnosis Supportive finding from history or examination"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Rheumatoid arthritis</td><td>FHx of RA</td></tr><tr><td>Recent STI symptoms consistent with Chlamydia</td><td></td></tr><tr><td>Reactive arthritis</td><td></td></tr><tr><td>Ankylosing spondylitis</td><td>Atraumatic lower back pain in addition to peripheral joints</td></tr><tr><td>Psoriatic nail changes</td><td></td></tr><tr><td>Psoriatic arthritis</td><td></td></tr><tr><td>Gout</td><td>Gouty tophi on examination</td></tr><tr><td>Gonorrhoea</td><td>Recent STI symptoms consistent with gonorrhoea</td></tr><tr><td>SLE</td><td>Malar flush</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
